<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { Activity, Download, FlaskConical, RefreshCw, Search, ShieldCheck, Trash2, TriangleAlert } from 'lucide-vue-next'
import { ApiError, api } from '../services/api'
import { useToastStore } from '../stores/toast'
import type { PaginatedResponse, Repository } from '../types/api'

type Tab='overview'|'diagnostics'|'recommendations'|'cleanup'
interface ClinicFinding { id:string; category:string; severity:string; action_class:string; code:string; title:string; description:string; evidence:Record<string,unknown>; risk:string; recommendation:string; action_available:string|null }
interface ClinicAnalysis { id:string; repository_id:string; job_id:string|null; status:string; score:number; score_breakdown:Record<string,{label?:string;points?:number;weight?:number;detail?:string}|number>; metrics:Record<string,unknown>; error:string|null; created_at:string; completed_at:string|null; findings:ClinicFinding[] }
interface CleanupProfile { id:string; repository_id:string; name:string; description:string|null; criteria:Record<string,unknown>; preservation_rules:Record<string,unknown>; canonical_checkpoint:Record<string,unknown>; enabled:boolean }
interface CleanupCandidate { id:string; resource_type:string; resource_key:string; resource_id:string|null; action_class:string; reason:string; dependencies:Array<Record<string,unknown>>; protected:boolean; selected:boolean; size_bytes:number|null; metadata:Record<string,unknown> }
interface CleanupAnalysis { id:string; repository_id:string; profile_id:string|null; job_id:string|null; reference:string; status:string; checkpoint:Record<string,unknown>; preservation_rules:Record<string,unknown>; metrics:Record<string,unknown>; dependency_graph:Record<string,unknown>; plan:Array<Record<string,unknown>>; dry_run:Record<string,unknown>; estimated_reclaimed_bytes:number; result:Record<string,unknown>; error:string|null; created_at:string; completed_at:string|null; candidates:CleanupCandidate[] }

const toasts=useToastStore(); const tab=ref<Tab>('overview'); const loading=ref(true); const busy=ref(''); const repositories=ref<Repository[]>([]); const selectedRepositoryId=ref(''); const clinic=ref<ClinicAnalysis[]>([]); const cleanup=ref<CleanupAnalysis[]>([]); const profiles=ref<CleanupProfile[]>([]); const selectedAnalysisId=ref('');
const analyzeForm=reactive({include_deep_git:true,include_actions:true,include_ghcr:true})
const profileForm=reactive({name:'Manutenção mensal',description:'',criteriaText:'{"runs_failed_days":30,"artifacts_days":30,"cache_days":14,"ghcr_untagged_days":30,"branches_merged_days":60}',preservationText:'{"preserve_default_branch":true,"preserve_latest_release":true,"preserve_last_releases":5,"preserve_protected_branches":true,"preserve_deployment_refs":true,"preserve_latest_image":true}',checkpointText:'{}'})
const cleanupForm=reactive({profile_id:'',criteriaText:'{}',preservationText:'{}',checkpointText:'{}'})
const selectedCleanup=computed(()=>cleanup.value.find(x=>x.id===selectedAnalysisId.value)||null)
const latestClinic=computed(()=>clinic.value[0]||null)
const selectedRepository=computed(()=>repositories.value.find(x=>x.id===selectedRepositoryId.value)||null)
const selectedIds=ref<string[]>([])
function err(error:unknown){return error instanceof ApiError?error.message:String(error)}
function jsonObject(value:string){const parsed=JSON.parse(value||'{}') as unknown;if(!parsed||Array.isArray(parsed)||typeof parsed!=='object')throw new Error('JSON deve ser um objeto.');return parsed as Record<string,unknown>}
function when(value:string|null){return value?new Date(value).toLocaleString('pt-BR'):'—'}
function bytes(value:number|null|undefined){if(!value)return '—';const units=['B','KB','MB','GB','TB'];let current=value,index=0;while(current>=1024&&index<units.length-1){current/=1024;index++}return `${current.toFixed(index?1:0)} ${units[index]}`}
function severityClass(value:string){return value==='critical'?'critical':value==='high'?'high':value==='medium'?'medium':value==='low'?'low':'info'}
function actionClass(value:string){return value.toLowerCase()}
async function loadRepos(){const items:Repository[]=[];let page=1,pages=1;do{const r=await api.get<PaginatedResponse<Repository>>(`/repositories?page=${page}&page_size=100`);items.push(...r.items);pages=r.pages;page++}while(page<=pages);return items}
async function loadRepositoryData(){if(!selectedRepositoryId.value)return;try{const [c,p,x]=await Promise.all([api.get<ClinicAnalysis[]>(`/platform/clinic?repository_id=${selectedRepositoryId.value}&limit=30`),api.get<CleanupProfile[]>(`/platform/cleanup/profiles?repository_id=${selectedRepositoryId.value}`),api.get<CleanupAnalysis[]>(`/platform/cleanup?repository_id=${selectedRepositoryId.value}&limit=30`)]);clinic.value=c;profiles.value=p;cleanup.value=x;if(x.length&&!selectedAnalysisId.value)selectedAnalysisId.value=x[0].id;if(!cleanupForm.profile_id&&p.length)cleanupForm.profile_id=p[0].id}catch(error){toasts.error('Falha ao carregar clínica',err(error))}}
async function load(){loading.value=true;try{repositories.value=await loadRepos();if(!selectedRepositoryId.value)selectedRepositoryId.value=repositories.value[0]?.id||'';await loadRepositoryData()}catch(error){toasts.error('Falha ao carregar Repository Clinic',err(error))}finally{loading.value=false}}
watch(selectedRepositoryId,async()=>{selectedAnalysisId.value='';await loadRepositoryData()})
watch(selectedCleanup,(value)=>{selectedIds.value=(value?.candidates||[]).filter(x=>x.selected).map(x=>x.id)})
async function run(key:string,fn:()=>Promise<void>){busy.value=key;try{await fn()}catch(error){toasts.error('Operação recusada',err(error))}finally{busy.value=''}}
async function analyzeClinic(){if(!selectedRepositoryId.value)return;await run('clinic',async()=>{const r=await api.post<{job_id:string}>('/platform/clinic/analyze',{repository_id:selectedRepositoryId.value,...analyzeForm});toasts.success('Análise clínica enfileirada',`Job ${r.job_id}. O score só será calculado com evidências reais.`)})}
async function createProfile(){await run('profile',async()=>{const p=await api.post<CleanupProfile>('/platform/cleanup/profiles',{repository_id:selectedRepositoryId.value,name:profileForm.name,description:profileForm.description||null,criteria:jsonObject(profileForm.criteriaText),preservation_rules:jsonObject(profileForm.preservationText),canonical_checkpoint:jsonObject(profileForm.checkpointText),enabled:true});toasts.success('Cleanup Profile criado',p.name);await loadRepositoryData();cleanupForm.profile_id=p.id})}
async function analyzeCleanup(){await run('cleanup-analyze',async()=>{const r=await api.post<{job_id:string}>('/platform/cleanup/analyze',{repository_id:selectedRepositoryId.value,profile_id:cleanupForm.profile_id||null,criteria:jsonObject(cleanupForm.criteriaText),preservation_rules:jsonObject(cleanupForm.preservationText),canonical_checkpoint:jsonObject(cleanupForm.checkpointText)});toasts.success('Cleanup Analysis enfileirada',`Job ${r.job_id}. Nenhum DELETE ocorre nesta etapa.`)})}
async function refreshCleanup(){await loadRepositoryData();if(selectedAnalysisId.value){const item=await api.get<CleanupAnalysis>(`/platform/cleanup/${selectedAnalysisId.value}`);const index=cleanup.value.findIndex(x=>x.id===item.id);if(index>=0)cleanup.value[index]=item;else cleanup.value.unshift(item)}}
async function saveSelection(){if(!selectedCleanup.value)return;await run('selection',async()=>{const updated=await api.put<CleanupAnalysis>(`/platform/cleanup/${selectedCleanup.value!.id}/selection`,{candidate_ids:selectedIds.value});const index=cleanup.value.findIndex(x=>x.id===updated.id);if(index>=0)cleanup.value[index]=updated;toasts.success('Seleção salva',`${selectedIds.value.length} candidato(s) selecionado(s).`)})}
async function dryRun(){if(!selectedCleanup.value)return;await run('dry-run',async()=>{await saveSelection();const r=await api.post<{job_id:string}>(`/platform/cleanup/${selectedCleanup.value!.id}/dry-run`,{});toasts.success('Dry Run enfileirado',`Job ${r.job_id}. O engine fará zero chamadas DELETE.`)})}
async function executeCleanup(){const analysis=selectedCleanup.value;if(!analysis)return;const expected=`EXECUTAR ${analysis.reference}`;const confirmation=window.prompt(`A limpeza executará somente os candidatos selecionados e não protegidos.\n\nDigite exatamente:\n${expected}`);if(confirmation!==expected)return;await run('execute',async()=>{await saveSelection();const r=await api.post<{job_id:string}>(`/platform/cleanup/${analysis.id}/execute`,{confirmation,create_backup:true});toasts.success('Cleanup enfileirado',`Job ${r.job_id}. Itens DESTRUCTIVE exigem backup concluído.`)})}
async function exportReport(){if(!selectedCleanup.value)return;await run('report',async()=>{const result=await api.download(`/platform/cleanup/${selectedCleanup.value!.id}/report.json`);const url=URL.createObjectURL(result.blob);const a=document.createElement('a');a.href=url;a.download=result.filename||`${selectedCleanup.value!.reference}.json`;a.click();URL.revokeObjectURL(url)})}
function toggleAllSafe(){if(!selectedCleanup.value)return;selectedIds.value=selectedCleanup.value.candidates.filter(x=>!x.protected&&x.action_class==='safe').map(x=>x.id)}
onMounted(load)
</script>

<template><div class="page-stack">
  <section class="page-heading"><div><span class="eyebrow">DIAGNÓSTICO EXPLICÁVEL</span><h2>Repository Clinic</h2><p>Diagnóstico técnico, evidências, recomendações e Deep Clean compartilhando o mesmo motor de análise.</p></div><button class="button secondary" :disabled="loading" @click="load"><RefreshCw :size="16"/>Atualizar</button></section>
  <section class="context"><label class="field"><span>Repositório</span><select v-model="selectedRepositoryId"><option v-for="repo in repositories" :key="repo.id" :value="repo.id">{{repo.full_name}}</option></select></label><div v-if="latestClinic" class="score"><span>Health Score</span><strong>{{latestClinic.score}}/100</strong><small>{{latestClinic.status}} · {{when(latestClinic.completed_at||latestClinic.created_at)}}</small></div></section>
  <nav class="tabs"><button :class="{active:tab==='overview'}" @click="tab='overview'">Overview</button><button :class="{active:tab==='diagnostics'}" @click="tab='diagnostics'">Diagnostics</button><button :class="{active:tab==='recommendations'}" @click="tab='recommendations'">Recommendations</button><button :class="{active:tab==='cleanup'}" @click="tab='cleanup'">Deep Clean</button></nav>

  <template v-if="tab==='overview'">
    <section class="panel"><header><div><strong>Analisar repositório</strong><span>O score só existe depois da coleta das evidências correspondentes.</span></div><FlaskConical :size="20"/></header><div class="checks"><label class="check"><input v-model="analyzeForm.include_deep_git" type="checkbox"/>Git profundo</label><label class="check"><input v-model="analyzeForm.include_actions" type="checkbox"/>Actions</label><label class="check"><input v-model="analyzeForm.include_ghcr" type="checkbox"/>GHCR</label></div><button class="button primary" :disabled="busy==='clinic'||!selectedRepository" @click="analyzeClinic"><Search :size="15"/>Executar análise clínica</button></section>
    <section v-if="latestClinic" class="score-grid"><article v-for="(component,key) in latestClinic.score_breakdown" :key="String(key)" class="metric"><span>{{typeof component==='object'?(component.label||key):key}}</span><strong>{{typeof component==='object'?(component.points??0):component}}<small v-if="typeof component==='object'">/{{component.weight??'—'}}</small></strong><p v-if="typeof component==='object'">{{component.detail}}</p></article></section>
    <section v-if="latestClinic" class="panel"><header><div><strong>Métricas observadas</strong><span>Dados utilizados na análise; não são percentuais fictícios.</span></div><Activity :size="19"/></header><pre>{{JSON.stringify(latestClinic.metrics,null,2)}}</pre></section>
  </template>

  <template v-else-if="tab==='diagnostics'">
    <section class="findings"><article v-for="finding in latestClinic?.findings||[]" :key="finding.id" class="finding"><header><div><span class="severity" :class="severityClass(finding.severity)">{{finding.severity}}</span><span class="class" :class="actionClass(finding.action_class)">{{finding.action_class}}</span></div><code>{{finding.category}} · {{finding.code}}</code></header><h3>{{finding.title}}</h3><p>{{finding.description}}</p><details><summary>Evidência</summary><pre>{{JSON.stringify(finding.evidence,null,2)}}</pre></details><div class="risk"><b>Risco:</b> {{finding.risk}}</div></article><div v-if="!latestClinic?.findings?.length" class="empty">Execute uma análise clínica para obter diagnósticos.</div></section>
  </template>

  <template v-else-if="tab==='recommendations'">
    <section class="findings"><article v-for="finding in latestClinic?.findings||[]" :key="finding.id" class="finding recommendation"><header><span class="severity" :class="severityClass(finding.severity)">{{finding.severity}}</span><span class="class" :class="actionClass(finding.action_class)">{{finding.action_class}}</span></header><h3>{{finding.title}}</h3><p>{{finding.recommendation}}</p><small v-if="finding.action_available">Ação disponível: {{finding.action_available}}</small></article><div v-if="!latestClinic?.findings?.length" class="empty">Nenhuma recomendação calculada ainda.</div></section>
  </template>

  <template v-else>
    <section class="warning"><TriangleAlert :size="19"/><div><strong>Analyze → Build Plan → Dry Run → Review → Backup → Confirm → Execute → Validate → Audit</strong><span>Nenhum candidato é apagado apenas por ser antigo. Recursos protegidos/checkpoints/deployments são avaliados antes.</span></div></section>
    <section class="panel"><header><div><strong>Cleanup Profile</strong><span>Salve regras genéricas por repositório; nenhum nome de projeto é hardcoded.</span></div><ShieldCheck :size="19"/></header><div class="grid cols-2"><label class="field"><span>Nome</span><input v-model="profileForm.name"/></label><label class="field"><span>Descrição</span><input v-model="profileForm.description"/></label></div><div class="grid cols-3"><label class="field"><span>Critérios JSON</span><textarea v-model="profileForm.criteriaText" class="code"/></label><label class="field"><span>Preservation Rules</span><textarea v-model="profileForm.preservationText" class="code"/></label><label class="field"><span>Canonical Checkpoint</span><textarea v-model="profileForm.checkpointText" class="code" placeholder='{"tag":"v1.5.0","branch":"main"}'/></label></div><button class="button secondary" :disabled="busy==='profile'" @click="createProfile">Salvar profile</button></section>
    <section class="panel"><header><div><strong>Repository Cleanup Analysis</strong><span>Mapeia Runs, Artifacts, Releases, Tags, Cache, GHCR e branches.</span></div><Search :size="19"/></header><label class="field"><span>Profile (opcional)</span><select v-model="cleanupForm.profile_id"><option value="">Análise avulsa</option><option v-for="profile in profiles" :key="profile.id" :value="profile.id">{{profile.name}}</option></select></label><button class="button primary" :disabled="busy==='cleanup-analyze'" @click="analyzeCleanup"><Search :size="15"/>Analisar repositório</button></section>
    <section v-if="cleanup.length" class="panel"><label class="field"><span>Análise</span><select v-model="selectedAnalysisId" @change="refreshCleanup"><option v-for="item in cleanup" :key="item.id" :value="item.id">{{item.reference}} · {{item.status}} · {{when(item.created_at)}}</option></select></label><div class="actions"><button class="button secondary" @click="refreshCleanup"><RefreshCw :size="14"/>Recarregar</button><button class="button ghost" @click="toggleAllSafe">Selecionar SAFE</button><button class="button secondary" :disabled="busy==='dry-run'||!selectedCleanup" @click="dryRun"><FlaskConical :size="14"/>Dry Run</button><button class="button danger-button" :disabled="busy==='execute'||selectedCleanup?.status!=='ready'" @click="executeCleanup"><Trash2 :size="14"/>Execute</button><button class="button ghost" @click="exportReport"><Download :size="14"/>Relatório JSON</button></div></section>
    <section v-if="selectedCleanup" class="summary-grid"><article><span>Referência</span><strong>{{selectedCleanup.reference}}</strong></article><article><span>Status</span><strong>{{selectedCleanup.status}}</strong></article><article><span>Recuperação estimada</span><strong>{{bytes(selectedCleanup.estimated_reclaimed_bytes)}}</strong></article><article><span>Checkpoint</span><strong><code>{{String(selectedCleanup.checkpoint.sha||selectedCleanup.checkpoint.tag||'—').slice(0,18)}}</code></strong></article></section>
    <section v-if="selectedCleanup" class="panel table-panel"><header><div><strong>Cleanup Preview</strong><span>Selecione granularmente. Itens protected não podem ser selecionados.</span></div></header><div class="table-wrap"><table><thead><tr><th></th><th>Classe</th><th>Tipo</th><th>Recurso</th><th>Motivo</th><th>Tamanho</th></tr></thead><tbody><tr v-for="item in selectedCleanup.candidates" :key="item.id" :class="{protected:item.protected}"><td><input v-model="selectedIds" type="checkbox" :value="item.id" :disabled="item.protected"/></td><td><span class="class" :class="actionClass(item.action_class)">{{item.action_class}}</span></td><td>{{item.resource_type}}</td><td><code>{{item.resource_key}}</code><small v-if="item.protected">PROTEGIDO</small></td><td>{{item.reason}}</td><td>{{bytes(item.size_bytes)}}</td></tr><tr v-if="!selectedCleanup.candidates.length"><td colspan="6" class="empty">Nenhum candidato encontrado.</td></tr></tbody></table></div><button class="button secondary" @click="saveSelection">Salvar seleção</button></section>
    <section v-if="selectedCleanup?.dry_run&&Object.keys(selectedCleanup.dry_run).length" class="panel"><header><div><strong>Dry Run</strong><span>Nenhuma chamada DELETE ocorre na simulação.</span></div></header><pre>{{JSON.stringify(selectedCleanup.dry_run,null,2)}}</pre></section>
    <section v-if="selectedCleanup?.result&&Object.keys(selectedCleanup.result).length" class="panel"><header><div><strong>Cleanup Report</strong><span>Resultado validado e preservado na auditoria.</span></div></header><pre>{{JSON.stringify(selectedCleanup.result,null,2)}}</pre></section>
  </template>
</div></template>

<style scoped>
.context{display:grid;grid-template-columns:minmax(260px,1fr) auto;gap:.8rem;align-items:end}.score{display:grid;min-width:190px;padding:.7rem .9rem;border:1px solid var(--border);border-radius:.85rem;background:var(--surface)}.score span,.score small{color:var(--text-muted);font-size:.62rem}.score strong{font-size:1.35rem;color:var(--text-strong)}.tabs{display:flex;gap:.3rem;overflow:auto;padding:.35rem;border:1px solid var(--border);border-radius:.85rem;background:var(--surface)}.tabs button{padding:.55rem .75rem;white-space:nowrap;color:var(--text-muted);border-radius:.6rem;background:transparent}.tabs button.active{color:var(--text-strong);background:var(--surface-raised);box-shadow:inset 0 0 0 1px var(--border)}.panel,.finding{padding:1rem;border:1px solid var(--border);border-radius:.9rem;background:var(--surface);box-shadow:var(--shadow-sm)}.panel>header{display:flex;justify-content:space-between;gap:.6rem;margin-bottom:.7rem}.panel header div{display:grid}.panel header span{color:var(--text-muted);font-size:.67rem}.checks,.actions{display:flex;gap:.65rem;flex-wrap:wrap;margin:.7rem 0}.score-grid,.summary-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:.7rem}.metric,.summary-grid article{padding:.8rem;border:1px solid var(--border);border-radius:.8rem;background:var(--surface)}.metric span,.summary-grid span{color:var(--text-muted);font-size:.62rem}.metric strong,.summary-grid strong{display:block;margin:.25rem 0;color:var(--text-strong);font-size:1rem}.metric small{font-size:.65rem}.metric p{margin:0;color:var(--text-muted);font-size:.65rem}.findings{display:grid;gap:.7rem}.finding header{display:flex;justify-content:space-between;gap:.5rem}.finding h3{margin:.55rem 0 .35rem;color:var(--text-strong)}.finding p{color:var(--text);line-height:1.55}.finding code{color:var(--text-muted);font-size:.62rem}.severity,.class{display:inline-flex;padding:.18rem .42rem;border-radius:999px;font-size:.56rem;font-weight:800;text-transform:uppercase}.severity.critical{color:white;background:var(--danger)}.severity.high{color:var(--danger);background:color-mix(in srgb,var(--danger) 10%,transparent)}.severity.medium{color:var(--warning);background:color-mix(in srgb,var(--warning) 10%,transparent)}.severity.low{color:var(--primary-strong);background:color-mix(in srgb,var(--primary) 10%,transparent)}.severity.info{color:var(--text-muted);background:var(--surface-raised)}.class.safe{color:var(--success);background:color-mix(in srgb,var(--success) 10%,transparent)}.class.review{color:var(--warning);background:color-mix(in srgb,var(--warning) 10%,transparent)}.class.destructive{color:var(--danger);background:color-mix(in srgb,var(--danger) 10%,transparent)}.risk{margin-top:.6rem;padding:.55rem;border-radius:.6rem;background:var(--surface-raised)}pre{max-height:32rem;overflow:auto;padding:.7rem;border:1px solid var(--border);border-radius:.65rem;background:var(--surface-raised);color:var(--text);font-size:.65rem}.grid{display:grid;gap:.7rem}.cols-2{grid-template-columns:repeat(2,minmax(0,1fr))}.cols-3{grid-template-columns:repeat(3,minmax(0,1fr))}.code{min-height:9rem;font-family:ui-monospace,SFMono-Regular,Consolas,monospace}.warning{display:flex;gap:.7rem;padding:.8rem;color:var(--warning);border:1px solid color-mix(in srgb,var(--warning) 30%,var(--border));border-radius:.8rem;background:color-mix(in srgb,var(--warning) 5%,var(--surface))}.warning div{display:grid}.warning span{font-size:.66rem}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;font-size:.68rem}th,td{padding:.6rem;border-bottom:1px solid var(--border-soft);text-align:left;vertical-align:top}th{color:var(--text-muted)}td small{display:block;color:var(--warning);font-size:.52rem}.protected{opacity:.62}.danger-button{color:#fff;background:var(--danger)}.empty{padding:1rem;text-align:center;color:var(--text-muted)}@media(max-width:820px){.context,.cols-2,.cols-3{grid-template-columns:1fr}.score{min-width:0}.finding header{align-items:flex-start;flex-direction:column}.summary-grid{grid-template-columns:1fr 1fr}}
</style>
